describe('Image Gallery Lightbox', () => {
    beforeEach(() => {
        cy.visit('/gallery'); // Replace with the actual URL of the gallery page
    });

    it('should open lightbox when an image is clicked', () => {
        cy.get('.gallery-image').first().click(); // Adjust selector as needed
        cy.get('.lightbox').should('be.visible'); // Adjust selector for lightbox
        cy.get('.lightbox img').should('have.attr', 'src').and('include', 'expected-image-src'); // Replace with expected image src
    });

    it('should close lightbox when close button is clicked', () => {
        cy.get('.gallery-image').first().click();
        cy.get('.lightbox .close-button').click(); // Adjust selector for close button
        cy.get('.lightbox').should('not.be.visible');
    });
});
